package br.com.fastfps.chunk; public final class ChunkUpdateTask implements Comparable<ChunkUpdateTask>{public final long key,generation;public final int priority,cost;public ChunkUpdateTask(long k,long g,int p,int c){key=k;generation=g;priority=p;cost=c;}public int compareTo(ChunkUpdateTask o){int p=Integer.compare(o.priority,priority);return p!=0?p:Long.compare(generation,o.generation);}}
